// Requirement: Stored type must have non-throwing move
struct DangerousItem {
    int* ptr;
    DangerousItem() : ptr(new int[1]) {}
    ~DangerousItem() { delete[] ptr; }

    // WARNING: This move constructor can throw (e.g., system failure).
    // Failure to mark 'noexcept' means STL cannot rely on strong guarantee
    // during container reallocation/move operations.
    DangerousItem(DangerousItem&& other)
    /* noexcept(true) is missing */
    {
        ptr = other.ptr;
        other.ptr = nullptr;
        // If an operation here throws: UNDEFINED BEHAVIOR
    }
};

std::vector<DangerousItem> container;
// If container resize triggers reallocation/move, and move throws:
// Internal container state is corrupted/undefined.
container.push_back(DangerousItem{});
